python3 -I - <<'EOF'
import re, json
lines = open('outputs/training.log', encoding='utf-8', errors='replace').read().split('\n')
# find panels
panels = []
cur = None
for i, ln in enumerate(lines):
    m = re.search(r'─ Step (\d+) ─', ln)
    if m:
        cur = {'step': int(m.group(1)), 'start': i, 'rows': []}
        panels.append(cur)
        continue
    if cur is None: continue
    if ln.startswith('╰'):
        cur['end'] = i; cur = None; continue
    cur['rows'].append(ln)
print('num panels', len(panels), [p['step'] for p in panels])

def parse_panel(p):
    # table rows: lines starting with '│ │' ; separators '│ ├'
    recs = []
    rec = None
    for ln in p['rows']:
        if ln.startswith('│ ├') or ln.startswith('│ ┡'):
            if rec: recs.append(rec)
            rec = {'prompt': [], 'completion': [], 'scores': []}
            continue
        if ln.startswith('│ └'):
            if rec: recs.append(rec)
            rec = None
            continue
        if ln.startswith('│ │') and rec is not None:
            cells = ln[3:].rstrip('│ ').split('│')
            cells = [c for c in cells]
            if len(cells) >= 6:
                rec['prompt'].append(cells[0].strip())
                rec['completion'].append(cells[1].rstrip())
                sc = [c.strip() for c in cells[2:6]]
                if any(sc): rec['scores'].append(sc)
    return recs

out = []
for p in panels:
    recs = parse_panel(p)
    for r in recs:
        comp = ' '.join(x.strip() for x in r['completion'])
        comp = re.sub(r'\s+', ' ', comp)
        out.append({'step': p['step'], 'scores': r['scores'][0] if r['scores'] else None, 'n_rows': len(r['completion']), 'completion': comp})
json.dump(out, open('/tmp/log_completions.json','w'), ensure_ascii=False, indent=1)
for o in out:
    print(f"step {o['step']:>3} scores={o['scores']} rows={o['n_rows']}")
    print('   ', o['completion'][:600])
    print('    ... TAIL:', o['completion'][-200:])
    print()
EOF

