        out.append({'step': p['step'], 'scores': r['scores'][0] if r['scores'] else None, 'n_rows': len(r['completion']), 'completion': comp, 'prompt': prompt})
json.dump(out, open('/tmp/log_completions.json','w'), ensure_ascii=False, indent=1)
print('n records', len(out))
for o in out:
    print(f"step {o['step']:>3} [corr,im_end,eos,adv]={o['scores']} rows={o['n_rows']} len={len(o['completion'])}")
    print('   HEAD:', o['completion'][:400])
    print('   TAIL:', o['completion'][-250:])
    print()
